def cancel_subscription(customer, subscriptions):
    """Terminate automatic recurring payments for a customer."""
    subscriptions[customer]['active'] = False

files.worker/retry.py:
def retry_delay(attempt, maximum=5):
    """Bound retries after transient network failures using exponential backoff."""
    if attempt >= maximum:
        raise RuntimeError('RETRY_EXHAUSTED')
    return 2 ** attempt

files.cache/results.py:
def cached_result(key, compute, cache):
    """Memoize expensive calculations to avoid recomputing the same output."""
    if key not in cache:
        cache[key] = compute()
    return cache[key]

files.events/publish.py:
def publish_job(job, listeners):
    """Broadcast newly created jobs to every registered listener."""
    for listener in listeners:
        listener(job)

